-- person: email the key, each platform's id a column (owner ruling 257-3, 13 Sep 2026).
--
-- Generated by `drizzle-kit generate` and then HAND-ORDERED, which is the whole reason this file does not
-- read like the generator's output. `person` is rebuilt from the Google Workspace directory and the member
-- pull by `slopweaver store identity`, so its rows are derived and regenerable — but every content row's
-- native author id lived ONLY inside the JSONB this file drops. It is carried onto
-- `content.author_native_id` before the column goes, `author_id` is released (the reconciler re-points it),
-- and only then is the old shape removed. Nothing a record said about who wrote it is lost, and the order
-- is what buys that: the generator emits the DROP COLUMN with the ADDs and would take the JSONB away while
-- the UPDATE that reads it was still to come.
--
-- Every statement below is the generator's own, in the two passes it produced (adds, then the drop),
-- with the data steps interleaved. `meta/0001_snapshot.json` is the second pass's snapshot, so a
-- `drizzle-kit generate` over this tree adds nothing — which is what the `drift` gate checks.
ALTER TABLE "content" ADD COLUMN "author_native_id" text;--> statement-breakpoint
-- Only an identity of the ROW'S OWN SOURCE, and the FIRST of them in array order. Both halves matter. A
-- cross-source fallback could only ever stamp a row with an id its platform never issued — a Slack member
-- id on a Linear row — which is worse than the null it would replace, because a null is visibly unresolved
-- while a wrong id resolves to the wrong human. And a person can legitimately carry TWO identities of one
-- source (GitHub's numeric account id beside its login), so an unordered join would pick between them
-- arbitrarily and could stamp the numeric id where the record named the login, which `store identity`'s
-- re-pointing then matches against nobody. `ordinality` makes the choice the array's own order, which is
-- the order the identity was appended in, so the primary identity wins over an alias.
UPDATE "content" c SET "author_native_id" = (
    SELECT e->>'nativeId'
    FROM jsonb_array_elements(p."identities") WITH ORDINALITY AS t(e, ord)
    WHERE e->>'source' = c."source"::text
    ORDER BY t.ord
    LIMIT 1)
  FROM "person" p
  WHERE c."author_id" = p."id" AND c."author_native_id" IS NULL;--> statement-breakpoint
UPDATE "content" SET "author_id" = NULL WHERE "author_id" IS NOT NULL;--> statement-breakpoint
-- `person` is empty from here: the rows are derived, `email` lands NOT NULL with no default, and the
-- candidate rows reference people this build is about to stop producing.
DELETE FROM "person_link_candidate";--> statement-breakpoint
DELETE FROM "person";--> statement-breakpoint
-- The identity-uniqueness trigger guarded the array and is not in `postMigrationStatements` any more; the
-- UNIQUE indexes below are what replace it. IF EXISTS because a database built after this lands never had it.
DROP TRIGGER IF EXISTS "trg_person_identity_unique" ON "person";--> statement-breakpoint
DROP FUNCTION IF EXISTS person_identity_unique();--> statement-breakpoint
DROP INDEX "idx_person_identities";--> statement-breakpoint
